#!/usr/bin/env bash
set -euo pipefail

REQUIRED_BASE_COMMIT="90e50e2924a5d99366cc89669f1ea61ec92a88cc"
TARGET_BRANCH="${1:-feature/media-final-acceptance}"

echo "[1/5] Fetching latest origin/main..."
git fetch origin main

if ! git merge-base --is-ancestor "$REQUIRED_BASE_COMMIT" origin/main; then
  echo "ERROR: origin/main does not contain required base commit $REQUIRED_BASE_COMMIT (PR405)" >&2
  exit 1
fi

echo "[2/5] Creating branch $TARGET_BRANCH from origin/main..."
git checkout -B "$TARGET_BRANCH" origin/main

echo "[3/5] Applying Kosmora media final acceptance files..."
python3 - <<'INNER_PY'
import base64, io, tarfile
payload = base64.b64decode('''''')
with tarfile.open(fileobj=io.BytesIO(payload), mode="r:gz") as tf:
    tf.extractall(".")
INNER_PY
chmod +x scripts/media-live-acceptance.mjs

echo "[4/5] Running media verification checks (typecheck, tests, secret scan, diff check)..."
if command -v pnpm >/dev/null 2>&1; then
  pnpm --filter @cosmora/model-gateway typecheck
  pnpm --filter @cosmora/api typecheck
  pnpm --filter @cosmora/web typecheck
  pnpm --filter @cosmora/api exec vitest run test/media-api.test.ts test/media-durable-lifecycle.test.ts test/media-routes.test.ts
fi
node scripts/check-secrets.mjs
git diff --check

echo "[5/5] Committing changes on $TARGET_BRANCH..."
git add packages/model-gateway/src/media/media-registry.ts \
  packages/model-gateway/src/media/openai-media-adapter.ts \
  apps/api/src/media/media-budget.ts \
  apps/api/src/media/media-store.ts \
  apps/api/src/media/media-service.ts \
  apps/api/src/media/media-routes.ts \
  apps/api/src/server.ts \
  apps/api/test/media-api.test.ts \
  apps/api/test/media-durable-lifecycle.test.ts \
  apps/api/test/media-routes.test.ts \
  apps/web/src/app/media-generation/media-panel.tsx \
  apps/web/src/app/voice/voice-composer.tsx \
  scripts/media-live-acceptance.mjs \
  docs/design/VISUAL_WAITLIST.md \
  docs/handoff/MEDIA_FINAL_ACCEPTANCE.md
git commit -m "feat(media): finalize Kosmora media contour acceptance, budget wiring, idempotency, and transport safety"

echo "Ready! To push and open PR:"
echo "  git push -u origin $TARGET_BRANCH"